// ── Abstract Products ────────────────────────────────────────────
class Button {
  render()  { throw new Error('render() not implemented'); }
  onClick() { throw new Error('onClick() not implemented'); }
}
class Input {
  render()    { throw new Error('render() not implemented'); }
  getValue()  { throw new Error('getValue() not implemented'); }
}

// ── Concrete Products: Light Theme ───────────────────────────────
class LightButton extends Button {
  render()  { return '<button style="background:#fff;color:#000">Click</button>'; }
  onClick() { return 'light-button-click'; }
}
class LightInput extends Input {
  #value = '';
  render()   { return '<input style="background:#fff;border:1px solid #ccc" />'; }
  getValue() { return this.#value || '(light input)'; }
}

// ── Concrete Products: Dark Theme ────────────────────────────────
class DarkButton extends Button {
  render()  { return '<button style="background:#333;color:#fff">Click</button>'; }
  onClick() { return 'dark-button-click'; }
}
class DarkInput extends Input {
  #value = '';
  render()   { return '<input style="background:#1a1a1a;border:1px solid #555" />'; }
  getValue() { return this.#value || '(dark input)'; }
}

// ── Abstract Factory ─────────────────────────────────────────────
class ThemeFactory {
  createButton() { throw new Error('createButton() not implemented'); }
  createInput()  { throw new Error('createInput() not implemented'); }
}

// ── Concrete Factories ───────────────────────────────────────────
class LightThemeFactory extends ThemeFactory {
  createButton() { return new LightButton(); }
  createInput()  { return new LightInput(); }
}
class DarkThemeFactory extends ThemeFactory {
  createButton() { return new DarkButton(); }
  createInput()  { return new DarkInput(); }
}

// ── Client: depends only on abstract types ───────────────────────
class LoginForm {
  #button;
  #input;

  constructor(factory) {          // inject factory
    this.#button = factory.createButton();
    this.#input  = factory.createInput();
  }

  render() {
    return [
      `Input:  ${this.#input.render()}`,
      `Button: ${this.#button.render()}`,
    ].join('\n');
  }
}

// ── Configuration selects the family ─────────────────────────────
function getFactory(theme) {
  const factories = {
    light: new LightThemeFactory(),
    dark:  new DarkThemeFactory(),
  };
  if (!factories[theme]) throw new Error(`Unknown theme: ${theme}`);
  return factories[theme];
}

const lightForm = new LoginForm(getFactory('light'));
console.log('=== Light Theme ===');
console.log(lightForm.render());

const darkForm = new LoginForm(getFactory('dark'));
console.log('=== Dark Theme ===');
console.log(darkForm.render());

// Adding a 'HighContrast' theme = one new factory class + two new product classes.
// LoginForm and getFactory registry need zero changes.

// ── Abstract Factory: structural skeleton ────────────────────────

// Abstract Products
class ProductA { featureA() { throw new Error('not implemented'); } }
class ProductB { featureB() { throw new Error('not implemented'); } }

// Family 1 concrete products
class ProductA1 extends ProductA { featureA() { return 'A1'; } }
class ProductB1 extends ProductB { featureB() { return 'B1 — compatible with A1'; } }

// Family 2 concrete products
class ProductA2 extends ProductA { featureA() { return 'A2'; } }
class ProductB2 extends ProductB { featureB() { return 'B2 — compatible with A2'; } }

// Abstract Factory
class AbstractFactory {
  createProductA() { throw new Error('not implemented'); }
  createProductB() { throw new Error('not implemented'); }
}

// Concrete Factories — each produces one consistent family
class ConcreteFactory1 extends AbstractFactory {
  createProductA() { return new ProductA1(); }
  createProductB() { return new ProductB1(); }
}
class ConcreteFactory2 extends AbstractFactory {
  createProductA() { return new ProductA2(); }
  createProductB() { return new ProductB2(); }
}

// Client — only knows AbstractFactory + abstract products
class Client {
  constructor(factory) {
    this._a = factory.createProductA();
    this._b = factory.createProductB();
  }
  run() {
    return `${this._a.featureA()} | ${this._b.featureB()}`;
  }
}

const c1 = new Client(new ConcreteFactory1());
console.log(c1.run()); // A1 | B1 — compatible with A1

const c2 = new Client(new ConcreteFactory2());
console.log(c2.run()); // A2 | B2 — compatible with A2
